{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Rates & Cohorts — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbf6f1;--accent:#8b5e3c;--muted:#7b6b5e;--card:#fff7f1;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:var(--muted);background:linear-gradient(180deg,#fbf6f1 0%, #fff 100%);}
    body{background-image:url("assets/img/pattern.svg");background-repeat:repeat;background-size:320px;padding:24px;}
    .wrap{max-width:980px;margin:20px auto;padding:28px;background:var(--card);border-radius:14px;box-shadow:0 8px 30px rgba(99,66,45,0.08)}
    header{display:flex;align-items:center;justify-content:space-between;gap:20px}
    .brand{display:flex;flex-direction:column}
    .brand h1{margin:0;font-size:18px;color:var(--accent)}
    .brand p{margin:0;font-size:12px}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none;font-weight:600}
    .hero{display:flex;gap:18px;align-items:center;margin-top:18px}
    .hero h2{margin:0;color:#523927}
    .lead{color:#6a584d}
    .columns{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:20px}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.8),var(--glass));padding:18px;border-radius:12px;border:1px solid rgba(139,94,60,0.06)}
    .price{font-size:28px;color:var(--accent);margin:6px 0}
    .btn{display:inline-block;padding:10px 14px;background:var(--accent);color:#fff;border-radius:10px;text-decoration:none;font-weight:700}
    .muted{font-size:13px;color:#8a7a70}
    .timeline{margin-top:10px}
    ul.tiers{list-style:none;padding:0;margin:10px 0}
    ul.tiers li{padding:6px 0;border-bottom:1px dashed rgba(120,98,78,0.06);font-size:14px}
    .small{font-size:13px}
    footer{margin-top:22px;border-top:1px dashed rgba(120,98,78,0.08);padding-top:14px;color:#6a584d}
    .cta-row{display:flex;gap:12px;align-items:center}
    .try{background:#fff;border:1px solid rgba(139,94,60,0.12);padding:10px 12px;border-radius:10px;cursor:pointer}
    @media(max-width:720px){.columns{grid-template-columns:1fr}.hero{flex-direction:column;align-items:flex-start}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div class="brand">
        <h1>{{BUSINESS_NAME}}</h1>
        <p class="muted">{{TAGLINE}}</p>
      </div>
      <nav aria-label="Main navigation">
        <a href="index.html">Home</a>
        <a href="about.html">Who I Am</a>
        <a href="programs.html">Circles</a>
        <a href="services.html">Offerings</a>
        <a href="pricing.html">Rates</a>
        <a href="testimonials.html">Praise</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Reach</a>
      </nav>
    </header>

    <section class="hero">
      <div>
        <h2>Small cohorts. Big steadiness.</h2>
        <p class="lead">Join a guided 6-week cohort that builds practical daily habits; each session folds into a gentle system you can keep. Cohorts open seasonally — spots are limited.</p>
        <div style="margin-top:12px" class="cta-row">
          <a class="btn" href="#enroll">Reserve a seat</a>
          <button class="try" data-action="openExercise">Try a 3‑minute reset</button>
          <a class="muted" href="#faq">How it works</a>
        </div>
      </div>
      <div class="card">
        <div class="muted">Upcoming Cohort</div>
        <div class="price">March Cohort — $480</div>
        <div class="small">6 weekly live sessions, peer circle, habit tracker, downloadable toolkit</div>
        <ul class="tiers">
          <li>Early bird (first 6): $420</li>
          <li>Standard: $480</li>
          <li>Sliding scale spots available — inquire</li>
        </ul>
        <div style="margin-top:10px"><a class="btn" href="#enroll">Reserve a spot</a></div>
      </div>
    </section>

    <section style="margin-top:18px">
      <div class="columns">
        <div class="card">
          <h3 style="margin-top:0">Cohort structure</h3>
          <div class="timeline small">Each week covers a simple practice + habitable micro-routine with a focus: energy, focus, movement, sleep rhythms, social micro-checks, transitions.</div>
          <ol style="margin-top:10px">
            <li>Live learning + group lab (60 min)</li>
            <li>Micro-practice to try daily (10 min or less)</li>
            <li>Personal checklist + journal prompt</li>
          </ol>
        </div>

        <div class="card">
          <h3 style="margin-top:0">Why cohorts?</h3>
          <p class="small">You get community cues and gentle accountability — not pressure. Practices are framed as experiments and tracked in a simple weekly checklist. If you prefer 1:1, you can reserve a combined package.</p>
          <div style="margin-top:12px"><a class="btn" href="#book">Reserve with me</a></div>
        </div>
      </div>
    </section>

    <section style="margin-top:18px" id="faq" class="card">
      <h3 style="margin-top:0">Common questions</h3>
      <div class="small">
        <strong>Is this therapy?</strong> No — these are habit frameworks and reflective tools for wellbeing, not medical care.
      </div>
      <div class="small" style="margin-top:8px">
        <strong>How many people per cohort?</strong> Usually 8–12 to keep the group intimate.
      </div>
      <div class="small" style="margin-top:8px">
        <strong>Need a payment plan?</strong> Yes — email {{EMAIL}} to request a plan.
      </div>
    </section>

    <footer>
      <div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap">
        <div class="muted">Questions? Call <strong>{{PHONE}}</strong> or <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
        <div class="muted">Based in {{CITY}}, {{STATE}}</div>
      </div>
    </footer>
  </div>

  <!-- Guided exercise modal -->
  <div id="exerciseModal" role="dialog" aria-hidden="true" style="position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(8,6,5,0.4);z-index:60">
    <div style="width:92%;max-width:560px;background:#fff;padding:20px;border-radius:12px;box-shadow:0 12px 40px rgba(0,0,0,0.25);">
      <button id="closeExercise" style="float:right;border:0;background:none;font-size:18px;cursor:pointer">✕</button>
      <h3 id="exerciseTitle">Reset — breathe</h3>
      <div id="exerciseBody" style="margin-top:8px;color:#564238">Simple guided choices to re-anchor. Choose a short path and follow the prompts.</div>
      <div style="margin-top:12px;display:flex;gap:10px;align-items:center">
        <select id="exerciseSelect" style="flex:1;padding:8px;border-radius:8px;border:1px solid #e6d5c9">
          <option value="breathing">Breathing (3 min)</option>
          <option value="journaling">Micro‑journaling (5 min)</option>
          <option value="intention">Intention setting (2 min)</option>
        </select>
        <button id="startExercise" class="btn">Begin</button>
      </div>
      <div id="exerciseControls" style="margin-top:14px;display:none;align-items:center;gap:8px">
        <div id="timer" style="font-weight:700;color:var(--accent)">00:00</div>
        <button id="pauseExercise" class="try">Pause</button>
        <button id="stopExercise" class="try">Stop</button>
      </div>
      <div id="exerciseGuide" style="margin-top:12px;color:#6b584e"></div>
    </div>
  </div>

  <script>
    // Modal controls
    (function(){
      const modal = document.getElementById('exerciseModal');
      const openButtons = document.querySelectorAll('[data-action="openExercise"]');
      const close = document.getElementById('closeExercise');
      const start = document.getElementById('startExercise');
      const select = document.getElementById('exerciseSelect');
      const guide = document.getElementById('exerciseGuide');
      const controls = document.getElementById('exerciseControls');
      const timerEl = document.getElementById('timer');
      const pauseBtn = document.getElementById('pauseExercise');
      const stopBtn = document.getElementById('stopExercise');
      const title = document.getElementById('exerciseTitle');

      let interval=null, remaining=0, paused=false;

      function openModal(){ modal.style.display='flex'; modal.setAttribute('aria-hidden','false'); }
      function closeModal(){ modal.style.display='none'; modal.setAttribute('aria-hidden','true'); stopRun(); }

      openButtons.forEach(b=>b.addEventListener('click',openModal));
      close.addEventListener('click',closeModal);

      function renderGuide(kind){
        if(kind==='breathing'){
          title.textContent='Breathing Reset';
          guide.innerHTML='<p>Follow the inhale/exhale rhythm. 4s inhale • 6s exhale. Repeat until the timer ends.</p>';
        } else if(kind==='journaling'){
          title.textContent='Micro‑journaling';
          guide.innerHTML='<p>Write three short lines: 1) What matters now? 2) One small step. 3) How I’ll notice progress.</p>';
        } else {
          title.textContent='Intention Setting';
          guide.innerHTML='<p>Pick a short intention for your next hour. Make it specific and kind.</p>';
        }
      }

      function startRun(){
        const kind = select.value; renderGuide(kind); controls.style.display='flex';
        if(kind==='breathing') remaining = 3*60; else if(kind==='journaling') remaining = 5*60; else remaining = 2*60;
        paused=false; updateTimer(); interval = setInterval(tick,1000);
      }

      function tick(){ if(!paused){ remaining--; if(remaining<=0){ stopRun(); alert('Well done — tiny practice complete.'); } updateTimer(); }}
      function updateTimer(){ const mm = String(Math.floor(remaining/60)).padStart(2,'0'); const ss = String(remaining%60).padStart(2,'0'); timerEl.textContent = mm+':'+ss; }
      function pauseRun(){ paused = !paused; pauseBtn.textContent = paused ? 'Resume' : 'Pause'; }
      function stopRun(){ clearInterval(interval); interval=null; controls.style.display='none'; timerEl.textContent='00:00'; }

      start.addEventListener('click',startRun);
      pauseBtn.addEventListener('click',pauseRun);
      stopBtn.addEventListener('click',stopRun);

      // Preload guide
      renderGuide(select.value);
      select.addEventListener('change',()=>renderGuide(select.value));
    })();
  </script>
</body>
</html>"} 
