{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fffaf6;--card:#fff;--accent:#8b5e3c;--muted:#6b5448}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial;background:var(--bg);color:var(--muted);padding:20px;background-image:url('assets/img/pattern.svg')}
    .wrap{max-width:980px;margin:12px auto;background:var(--card);padding:20px;border-radius:12px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:18px;margin-top:18px}
    .form{background:#fff;padding:14px;border-radius:10px}
    label{display:block;font-size:13px;margin-top:8px;color:#5f483f}
    input,select,textarea{width:100%;padding:8px;margin-top:6px;border-radius:8px;border:1px solid #e6d5c9;font-size:14px}
    .btn{display:inline-block;padding:10px 14px;background:var(--accent);color:#fff;border-radius:10px;text-decoration:none;border:0;cursor:pointer}
    .tools{background:linear-gradient(180deg,#fff7f2,#fff);padding:14px;border-radius:10px}
    .habit-card{background:#fff;padding:12px;border-radius:10px;border:1px solid rgba(139,94,60,0.06)}
    ul{padding-left:18px}
    .print{display:inline-block;margin-top:10px;padding:8px 10px;border-radius:9px;background:#fff;border:1px solid rgba(139,94,60,0.12);cursor:pointer}
    footer{margin-top:20px;color:#7d6559;font-size:13px}
    @media(max-width:880px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <div style="font-size:12px;color:#7d6559">Reserve a spot or schedule a discovery chat</div>
      </div>
      <nav>
        <a href="index.html">Home</a>
        <a href="programs.html">Circles</a>
        <a href="pricing.html">Rates</a>
        <a href="testimonials.html">Praise</a>
      </nav>
    </header>

    <main class="grid">
      <section>
        <div class="form">
          <h3 style="margin-top:0">Reserve a discovery chat</h3>
          <p class="small">Pick a time and tell me a little about your current rhythm. Discovery chats are 20 minutes.</p>
          <label for="name">Your name</label>
          <input id="name" placeholder="First and last">
          <label for="email">Email</label>
          <input id="email" placeholder="you@example.com">
          <label for="phone">Phone (optional)</label>
          <input id="phone" placeholder="(555) 555‑5555">
          <label for="type">I’m interested in</label>
          <select id="type">
            <option>Next cohort</option>
            <option>1:1 package</option>
            <option>Corporate / team</option>
          </select>
          <label for="time">Preferred time</label>
          <input id="time" placeholder="e.g. Tue afternoon">
          <label for="notes">Anything to know (short)</label>
          <textarea id="notes" rows="4" placeholder="What would you like to focus on?"></textarea>
          <div style="margin-top:10px;display:flex;gap:10px;align-items:center">
            <button class="btn" id="submitBook">Reserve a chat</button>
            <button class="print" id="startHabit">Create a 7‑day starter</button>
          </div>
          <div id="bookMsg" style="margin-top:10px;color:#5f483f;font-size:13px"></div>
        </div>

        <div style="margin-top:12px" class="habit-card" id="habitArea">
          <h4 style="margin:0">7‑Day Starter (preview)</h4>
          <div id="habitPreview" style="margin-top:8px;color:#644a3f">Create a short, printed checklist to try for a week. Click "Create" above.</div>
        </div>
      </section>

      <aside class="tools">
        <h4 style="margin-top:0">Quick tools</h4>
        <div style="font-size:13px;color:#5e4a41">If you prefer to test a micro practice now, try the guided walk‑through.</div>
        <div style="margin-top:10px">
          <button class="print" data-action="openExercise">Try a 3‑minute practice</button>
        </div>
        <hr style="margin:12px 0;border:none;border-top:1px dashed rgba(120,98,78,0.08)">
        <div style="font-size:13px;color:#5e4a41">Need something printable? Build a 7‑day checklist and print it for your fridge or journal.</div>
      </aside>
    </main>

    <footer>
      <div>Questions or group bookings? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • {{PHONE}}</div>
    </footer>
  </div>

  <!-- Habit builder and print functionality -->
  <script>
    (function(){
      const startBtn = document.getElementById('startHabit');
      const preview = document.getElementById('habitPreview');
      const submit = document.getElementById('submitBook');
      const msg = document.getElementById('bookMsg');

      function sampleOptions(){
        return {
          focus: ['Energy', 'Sleep transition', 'Midday reset', 'Evening wind‑down', 'Focus burst', 'Move more', 'Gratitude'],
          microHabits: {
            'Energy': 'Open a window + 1 minute stretch upon sitting down',
            'Sleep transition': 'Dim lights 30m before bed + 2 deep breaths',
            'Midday reset': 'Two slow breaths and 30 seconds walk',
            'Evening wind‑down': 'Write one good thing before screens',
            'Focus burst': 'Set 15 minute timer and single focus task',
            'Move more': 'Stand and stretch every hour for 2 minutes',
            'Gratitude': 'Name one small win from today'
          }
        }
      }

      function buildWeek(){
        const s = sampleOptions();
        const choices = Object.keys(s.microHabits);
        const week = [];
        // Rotate suggestions so each day feels distinct
        for(let d=0; d<7; d++){
          const key = choices[d % choices.length];
          week.push({day: 'Day '+(d+1), habit: s.microHabits[key]});
        }
        return week;
      }

      function renderPreview(week){
        let html = '<div style="font-size:14px"><strong>Your 7‑day checklist</strong></div>'; 
        html += '<ol style="margin:8px 0 0 18px">';
        week.forEach(w=>{ html += '<li style="margin:6px 0;color:#5b4336">'+w.habit+'</li>'; });
        html += '</ol>';
        html += '<div style="margin-top:10px"><button id="printChecklist" class="btn">Print checklist</button></div>';
        preview.innerHTML = html;
        document.getElementById('printChecklist').addEventListener('click',()=>printChecklist(week));
      }

      function printChecklist(week){
