  <script>
    // Modal with simple guided steps (shared across pages)
    (function(){
      const modal = document.getElementById('exerciseModal');
      const openButtons = document.querySelectorAll('[data-action="openExercise"]');
      const close = document.getElementById('closeExercise');
      const start = document.getElementById('startExercise');
      const select = document.getElementById('exerciseSelect');
      const guide = document.getElementById('exerciseGuide');
      const controls = document.getElementById('exerciseControls');
      const timerEl = document.getElementById('timer');
      const pauseBtn = document.getElementById('pauseExercise');
      const stopBtn = document.getElementById('stopExercise');
      const title = document.getElementById('exerciseTitle');
      let interval=null, remaining=0, paused=false;

      function openModal(){ modal.style.display='flex'; modal.setAttribute('aria-hidden','false'); }
      function closeModal(){ modal.style.display='none'; modal.setAttribute('aria-hidden','true'); stopRun(); }
      openButtons.forEach(b=>b.addEventListener('click',openModal));
      close.addEventListener('click',closeModal);

      function renderGuide(kind){
        if(kind==='breathing'){
          title.textContent='Breathing — 3 minutes';
          guide.innerHTML='<p>Try: 4s inhale • 6s exhale. Continue with soft focus on breath. If mind wanders, notice and return.</p>';
        } else if(kind==='journaling'){
          title.textContent='Micro‑journaling — 5 minutes';
          guide.innerHTML='<p>Prompt: What small step would make today better? Write a sentence, then one possible next action.</p>';
        } else {
          title.textContent='Intention setting — 2 minutes';
          guide.innerHTML='<p>Pick a single clear intention for the next hour. Keep it positive and tiny.</p>';
        }
      }

      function startRun(){ const kind = select.value; renderGuide(kind); controls.style.display='flex'; if(kind==='breathing') remaining=180; else if(kind==='journaling') remaining=300; else remaining=120; paused=false; updateTimer(); interval = setInterval(tick,1000);} 
      function tick(){ if(!paused){ remaining--; if(remaining<=0){ stopRun(); alert('You completed the mini‑practice. Nice work.'); } updateTimer(); }}
      function updateTimer(){ const mm = String(Math.floor(remaining/60)).padStart(2,'0'); const ss = String(remaining%60).padStart(2,'0'); timerEl.textContent = mm+':'+ss; }
      function pauseRun(){ paused = !paused; pauseBtn.textContent = paused ? 'Resume' : 'Pause'; }
      function stopRun(){ clearInterval(interval); interval=null; controls.style.display='none'; timerEl.textContent='00:00'; }

      start.addEventListener('click',startRun);
      pauseBtn.addEventListener('click',pauseRun);
      stopBtn.addEventListener('click',stopRun);

      // initial guide
      renderGuide(select.value);
      select.addEventListener('change',()=>renderGuide(select.value));
    })();
  </script>
